restoreViewState(s) {
        if (!this.tb || !this.tb.hasRealView) {
            return;
        }
        const codeEditorState = s;
        if (codeEditorState && codeEditorState.cursorState && codeEditorState.viewState) {
            const cursorState = codeEditorState.cursorState;
            if (Array.isArray(cursorState)) {
                if (cursorState.length > 0) {
                    this.tb.viewModel.restoreCursorState(cursorState);
                }
            }
            else {
                // Backwards compatibility
                this.tb.viewModel.restoreCursorState([cursorState]);
            }
            this.f.restoreViewState(codeEditorState.contributionsState || {});
            const reducedState = this.tb.viewModel.reduceRestoreState(codeEditorState.viewState);
            this.tb.view.restoreState(reducedState);
        }
    }
